"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[505],{5943(e){e.exports=JSON.parse('{"title":"React\uc5d0\uc11c INP \uac1c\uc120\ud558\uae30","date":"2024-12-12","coverUrl":"/kudzu-based-bench/assets/notion/bb6da89f5ba97fb3.png","html":"<h2 data-notion-block-id=\\"156e548d-8a8e-80df-95e3-c34f92e4fc7f\\" id=\\"156e548d-8a8e-80df-95e3-c34f92e4fc7f\\">React\uc5d0\uc11c INP \uac1c\uc120\ud558\uae30</h2><a href=\\"https://kurtextrem.de/posts/improve-inp-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kurtextrem.de/posts/improve-inp-react</a><p data-notion-block-id=\\"156e548d-8a8e-80d1-8cff-d947e70be36b\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/829975f7-5164-444d-a732-cb269bba2179#c1499555-1312-4ac0-8502-2c4d52d5eba9\\">INP\ub97c \uac1c\uc120\ud558\uae30 \uc704\ud55c \ud328\ud134</a> \uc800\uc790\uc758 React\uc5d0\uc11c INP\ub97c \uac1c\uc120\ud558\uae30 \uc704\ud55c \uae30\uc220\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <code>use*Effect</code>\uc774 \uc5b8\uc81c \uc2e4\ud589\ub418\ub294\uc9c0\uc5d0 \ub300\ud55c \uae00(<a href=\\"https://jser.dev/2023-07-02-use-insertion-effect/\\"><code>useInsertionEffect</code></a><a href=\\"https://jser.dev/2023-07-02-use-insertion-effect/\\">\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uac00</a>)\ub3c4 \uac19\uc774 \ubcf4\uba74 \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156e548d-8a8e-8008-8dee-ccaaa4f972dd\\" id=\\"156e548d-8a8e-8008-8dee-ccaaa4f972dd\\"><code>try...catch</code> \ucd5c\ub300\ud55c \uc4f0\uc9c0 \ub9c8\uc138\uc694</h2><a href=\\"https://www.joshuakgoldberg.com/blog/try-catch-as-little-as-possible/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshuakgoldberg.com/blog/try-catch-as-little-as-possible/</a><p data-notion-block-id=\\"156e548d-8a8e-8032-888a-dc3a7d86bcf2\\"><code>try...catch</code>\ub85c \uac80\uc99d\ud558\ub294 \ubd80\ubd84\uc744 \ucd5c\uc18c\ud55c\uc73c\ub85c \uc720\uc9c0\ud574\uc57c \ud558\ub294 \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c, React\uc758 <code>&#x3C;Errorboundary></code>\ub610\ud55c \uc801\uc808\ud55c \uacbd\uacc4\ub97c \uac19\uace0 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4. <a href=\\"https://www.brandondail.com/posts/fault-tolerance-react\\">Fault tolerance \uac1c\ub150\uc744 \ubc14\ud0d5\uc73c\ub85c </a><a href=\\"https://www.brandondail.com/posts/fault-tolerance-react\\"><code>&#x3C;Errorboundary></code></a><a href=\\"https://www.brandondail.com/posts/fault-tolerance-react\\">\uc758 \uc801\uc808\ud55c \uacbd\uacc4\uc758 \uc608\uc2dc\ub97c \ud480\uc5b4\ub0b4\ub294 \uae00</a> \ub610\ud55c \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156e548d-8a8e-80aa-ab77-d7f3c0cf3002\\" id=\\"156e548d-8a8e-80aa-ab77-d7f3c0cf3002\\">TypeScript \ub3c4\uc785 \uc2dc\uac04 \ub2e8\ucd95\ud558\uae30</h2><a href=\\"https://medium.com/airtable-eng/a-leap-in-the-evolution-of-airtables-codebase-scaling-typescript-to-thousands-of-projects-734326c3a553\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/airtable-eng/a-leap-in-the-evolution-of-airtables-codebase-scaling-typescript-to-thousands-of-projects-734326c3a553</a><p data-notion-block-id=\\"156e548d-8a8e-80b9-9385-f17a2d7bbe86\\">TypeScript\uc758 <code>isolationDeclaration</code>\uae30\ub2a5\uacfc \uc5ec\ub7ec \ud234(\ubaa8\ub178\ub808\ud3ec, AI\u2026)\uc744 \uc0ac\uc6a9\ud574\uc11c \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \ub3c4\uc785\uc744 \ube60\ub974\uac8c \uc9c4\ud589\ud55c \uc608\uc2dc\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156e548d-8a8e-80e6-8052-c87bec5d771e\\" id=\\"156e548d-8a8e-80e6-8052-c87bec5d771e\\">Tailwind 4\uc5d0 \ub300\ud55c \uc758\uacac</h2><a href=\\"https://nmn.sh/blog/2024-11-30-thoughts-on-tailwind-4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nmn.sh/blog/2024-11-30-thoughts-on-tailwind-4</a><p data-notion-block-id=\\"156e548d-8a8e-8043-9df6-cfa680939d7d\\">Tailwind 4\uc5d0 \ub3c4\uc785\ub41c \uc5ec\ub7ec \uae30\ub2a5\uc5d0 \ub300\ud55c \uc758\uacac\uc744 \ub9d0\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uae00 \ub9c8\uc9c0\ub9c9\uc5d0 \uc801\ud600\uc788\ub4ef \uadfc\ubcf8\uc801\uc778 \ubb38\uc81c\uc810\uc744 \ub9ce\uc774 \ud574\uacb0\ud558\uc9c0\ub294 \ubabb\ud588\uc9c0\ub9cc, \uc774\uc804\uc5d0 \ube44\ud574 \uc9c0\uc6d0 \ubc94\uc704\uac00 \ub298\uc5b4\ub09c \uac83\uc740 \uc8fc\ubaa9\ud560\ub9cc \ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"156e548d-8a8e-8072-bb82-eca8b10f7823\\" id=\\"156e548d-8a8e-8072-bb82-eca8b10f7823\\">\uc624\ud504\ub77c\uc778 \uc218\uc815 \uc9c0\uc6d0\uacfc \ud611\uc5c5 \uae30\ub2a5\uc758 \ucda9\ub3cc</h2><a href=\\"https://www.moment.dev/blog/lies-i-was-told-pt-1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.moment.dev/blog/lies-i-was-told-pt-1</a><p data-notion-block-id=\\"156e548d-8a8e-80a8-bed9-f36ec5976414\\">\ud611\uc5c5 \uae30\ub2a5\uacfc \uc624\ud504\ub77c\uc778 \uc218\uc815 \uae30\ub2a5\uacfc \ucda9\ub3cc\uc774 \uc790\uc8fc \uc77c\uc5b4\ub098\ub294\ub370, \uc54c\uace0\ub9ac\uc998(CRDT, OT)\uc758 \ubb38\uc81c\ubcf4\ub2e4\ub294 UX\uc758 \ubb38\uc81c\uc77c \uc218\ub3c4 \uc788\ub2e4\ub294 \uc7ac\ubc0c\ub294 \uad00\uc810\uc744 \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://news.ycombinator.com/item?id=42343953\\">Ycombinator</a> \ub313\uae00\uc5d0 \uc801\ud78c <a href=\\"https://www.inkandswitch.com/upwelling/\\">\ucda9\ub3cc \uad00\ub9ac(\uc640 \ub2e4\ub978 \uc5ec\ub7ec \uae30\ub2a5\uc744 \ub2e4\ub8ec) \ub17c\ubb38</a>\uc774\ub098 <a href=\\"https://supabase.com/blog/postgres-crdt#limitations\\">CRDT\uc640 Postgres\uc758 \ud2b9\uc9d5\uc73c\ub85c \uc778\ud504\ub77c \ubd80\ud558\ub97c \uc870\uc2ec\ud574\uc57c \ud55c\ub2e4</a>\ub294 \ub313\uae00\uc774 \ub208\uc5d0 \ub744\ub124\uc694.</p><h2 data-notion-block-id=\\"159e548d-8a8e-806c-8a0e-c930968a469b\\" id=\\"159e548d-8a8e-806c-8a0e-c930968a469b\\">ts-blank-space\uc640 \ud2b8\ub79c\uc2a4\ud30c\uc77c \uac1c\uc120</h2><a href=\\"https://www.youtube.com/watch?v=ZiD5zWlHBnY\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=ZiD5zWlHBnY</a><p data-notion-block-id=\\"159e548d-8a8e-8003-b491-dfaddefadc3e\\">\ub77c\uc774\ube0c\ub7ec\ub9ac \uc18c\uac1c \ubc1c\ud45c\uc774\uc9c0\ub9cc, \ud2b8\ub79c\uc2a4\ud30c\uc77c \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uac83\uacfc \uc81c\ud55c\uc801\uc778 \uc0c1\ud669\uc5d0\uc11c <a href=\\"https://www.bloomberg.com/company/stories/10-insights-adopting-typescript-at-scale/\\">\ubaa8\ub358 \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \ubc29\uc2dd \ucf54\ub4dc</a>\ub294 \ub2e4\ub978 \uc5b8\uc5b4\ub85c \uc791\uc131\ub41c \ud2b8\ub79c\uc2a4\ud30c\uc77c\ub7ec\uc640 \ube44\uc2b7\ud55c \uc18d\ub3c4\ub97c \ubcf4\uc5ec\uc904 \uc218 \uc788\ub2e4\ub97c \uc18c\uac1c\ud558\ub294 \uac83\uc740 \ud06c\uac8c \ub2e4\uac00\uc624\ub124\uc694. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/dadb3439-b509-4f21-b8a3-4646fdd233af#ac2fc48b-0366-4e22-b549-ca8a10832fda\\">Polyfill\uc740 \ud544\uc694\ud560\ub54c\ub9cc</a>\uc774\ub77c\ub294 \uae00\ub3c4 \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156e548d-8a8e-8050-8583-d4ae64644c07\\" id=\\"156e548d-8a8e-8050-8583-d4ae64644c07\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \uac00\ub3c5\uc131</h2><a href=\\"https://sapegin.me/blog/dont-make-me-think/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sapegin.me/blog/dont-make-me-think/</a><p data-notion-block-id=\\"156e548d-8a8e-80a1-a90c-f6ce2a1e0e29\\">\uc6d0\ub77c\uc778 \ucf54\ub4dc\ub098, \ubcf4\ud3b8\ud654\ub41c API\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ucf54\ub4dc\u2026. JS\uc5d0\uc11c\uc758 \uac00\ub3c5\uc131\uc744 \ud574\uce58\ub294 \uc5ec\ub7ec \ud328\ud134\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uba87 \uac00\uc9c0\ub294 \ud754\ud788 \ubcfc \uc218 \uc788\ub294 \ucf54\ub4dc\ub294 \uc544\ub2c8\uc9c0\ub9cc, \ub0b4\uac00 \uc0ac\uc6a9\ud558\ub294 \ucf54\ub4dc \ud328\ud134\uc774 \uc788\ub294\uc9c0 \ub418\ub3cc\uc544\ubcf4\uae30 \uc704\ud574 \ubcfc\ub9cc \ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"156e548d-8a8e-809d-b5b0-ea53429df932\\" id=\\"156e548d-8a8e-809d-b5b0-ea53429df932\\">CSS\ub9cc\uc73c\ub85c \ubc94\uc704 input \ub9cc\ub4e4\uae30</h2><a href=\\"https://muffinman.io/blog/native-dual-range-input/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://muffinman.io/blog/native-dual-range-input/</a><p data-notion-block-id=\\"156e548d-8a8e-8041-a9e1-d21c45ae71c6\\">CSS\uc640 \uac04\ub2e8\ud55c JS\ub85c \ubc94\uc704 input\uc744 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156e548d-8a8e-80a3-a3c4-c943cf5366ba\\" id=\\"156e548d-8a8e-80a3-a3c4-c943cf5366ba\\">\ud0c0\uc785\ub9cc \uac00\uc838\uc624\uae30</h2><a href=\\"https://echobind.com/post/sharing-types-and-code-between-the-server-and-client\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://echobind.com/post/sharing-types-and-code-between-the-server-and-client</a><p data-notion-block-id=\\"159e548d-8a8e-80b7-b498-d15e4df7c95a\\">\ud0c0\uc785\ub9cc \uac00\uc838\uc624\uae30 \uc704\ud55c \ud0c0\uc785\ub9cc \uac00\uc838\uc624\ub294 \uae30\ub2a5\uc744 \uc18c\uac1c\ud558\ub294 \uc9e7\uc740 \uae00\uc785\ub2c8\ub2e4. \ud0c0\uc785\ub9cc \uc0ac\uc6a9\ud558\ub294\ub370 \ud0c0\uc785\ub9cc \uac00\uc838\uc624\uc9c0 \uc54a\ub294 \uacbd\uc6b0 \ucef4\ud30c\uc77c \ud06c\uae30\uc5d0 \ud070 \uc601\ud5a5\uc744 \ub07c\uce58\ub2c8 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156e548d-8a8e-8095-8c2b-c704796ff54e\\" id=\\"156e548d-8a8e-8095-8c2b-c704796ff54e\\"><code>backdrop-filter</code> \uc0b4\ud3b4\ubcf4\uae30</h2><a href=\\"https://www.joshwcomeau.com/css/backdrop-filter/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/css/backdrop-filter/</a><a href=\\"https://www.tyleo.com/html-glass.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.tyleo.com/html-glass.html</a><p data-notion-block-id=\\"159e548d-8a8e-803e-be07-e28defb47c5c\\">\ub450 \uae00 \ubaa8\ub450 <code>backdrop-filter</code>\uc18d\uc131\uc744 \uc774\uc6a9\ud574 \uc720\ub9ac\uc640 \uac19\uc740 \ud6a8\uacfc\ub97c \uc8fc\uae30 \uc704\ud55c \uad6c\ud604\ud574\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \ub450 \uae00\uc774 \uad6c\ud604 \ubc29\uc2dd\uc774 \ub2e4\ub974\ubbc0\ub85c CSS \uc811\uadfc \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\ub3c4 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"156e548d-8a8e-807c-9647-ee03be95ea5a\\" id=\\"156e548d-8a8e-807c-9647-ee03be95ea5a\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://astro.build/blog/astro-5/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-5/</a><a href=\\"https://react.dev/blog/2024/12/05/react-19\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/blog/2024/12/05/react-19</a><p data-notion-block-id=\\"156e548d-8a8e-8077-827d-dbfbe0d35848\\">Vite 6\uc640 Content Layer, server island\u2026\uac00 \ucd94\uac00\ub41c Astro 5\ubc84\uc804\uacfc \uc5ec\ub7ec \ud6c5\uacfc \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc774 \ud3ec\ud568\ub41c React 19\uac00 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156e548d-8a8e-80bc-aa29-f91c2b1fad70\\" id=\\"156e548d-8a8e-80bc-aa29-f91c2b1fad70\\">\ubc88\uc678. AI\uc640 \uac1c\ubc1c \uae30\uc220</h2><a href=\\"https://addyo.substack.com/p/the-70-problem-hard-truths-about\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://addyo.substack.com/p/the-70-problem-hard-truths-about</a><a href=\\"https://www.builder.io/blog/ai-dev-skill\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.builder.io/blog/ai-dev-skill</a><p data-notion-block-id=\\"157e548d-8a8e-802f-b8d1-faff73c2d30a\\">\ubc88\uc678\ub85c AI\uac00 \ud504\ub85c\ud1a0\ud0c0\uc774\ud551, \ubc18\ubcf5\uc791\uc5c5\uc5d0\ub294 \ub2a5\ud574\ub3c4 \ubcf5\uc7a1\ud55c \ud788\uc2a4\ud1a0\ub9ac/\uc694\uad6c\uc0ac\ud56d\uc774 \ub2f4\uae34 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30\ub294 \ud798\ub4e4\ub2e4\ub294 \uad00\uc810\uc774 \ub2f4\uae34 \uae00\uc785\ub2c8\ub2e4. \ub098\uc911\uc5d0\ub294 \ubc14\ub014\uc9c0\ub3c4 \ubaa8\ub974\uaca0\uc9c0\ub9cc, \uc801\uc808\ud55c \uad00\uc810\uc774\ub77c \uc0dd\uac01\ud574 \uac00\uc838\uc653\uc2b5\ub2c8\ub2e4.</p>"}')}}]);